<header class="header shell"><a class="logo" href="#main" aria-label="OZON × DPD — главная">${t}</a><nav class="desktop-nav" aria-label="Главное меню"><a href="#how">Как работает</a><a href="#features">Возможности</a><a href="#faq">FAQ</a></nav><a class="cabinet-link" href="${o}/login" target="_blank" rel="noopener">Личный кабинет ${i(`arrow`)}</a><button class="menu-toggle" aria-label="Открыть меню" aria-expanded="false" aria-controls="mobile-nav">${i(`menu`)}</button></header>
